#!/usr/bin/env python3
"""Build a standalone stats report and a reproducible source bundle."""
import argparse,json,subprocess,shutil,csv,hashlib,zipfile
from pathlib import Path
parser=argparse.ArgumentParser();parser.add_argument('--results',required=True,type=Path);parser.add_argument('--supplemental',type=Path);parser.add_argument('--output',required=True,type=Path);parser.add_argument('--node',default='node');a=parser.parse_args()
root=Path(__file__).resolve().parent.parent;out=a.output;out.mkdir(parents=True,exist_ok=True)
meta=json.loads((a.results/'summary.json').read_text());experiments=[];full=[]
for folder in [a.results]+([a.supplemental] if a.supplemental else []):
 for file in sorted(folder.glob('*.json')):
  item=json.loads(file.read_text())
  if isinstance(item,dict) and 'id' in item and 'summary' in item and 'runs' in item:experiments.append({k:v for k,v in item.items() if k!='runs'});full.append(item)
config=json.loads((a.results/'config.json').read_text());candidate=json.loads(json.dumps(config));candidate['preset']='simulation-candidate-cavalry3';candidate['enemies'][next(i for i,u in enumerate(candidate['enemies']) if u['id']=='demon')]['hp']=3;candidate['players'][next(i for i,u in enumerate(candidate['players']) if u['id']=='lodge-3')]['damage']=3;candidate['simulationSettings']={'earlyPractice':True,'practiceReward':20}
formation=subprocess.run([a.node,str(root/'simulation/check-formations.cjs')],check=True,capture_output=True,text=True);(out/'simulation-formation-check.json').write_text(formation.stdout)
(out/'simulation-candidate.json').write_text(json.dumps(candidate,indent=2)+'\n');(out/'simulation-baseline.json').write_text(json.dumps(config,indent=2)+'\n')
examples=meta['examples']
for strategy in ['infantry','ranged','mounted','casters','mixed']:
 seed=next(e['seed'] for e in examples if e['experiment']=='baseline' and e['strategy']==strategy)
 tmp=out/(strategy+'-trace.json')
 subprocess.run([a.node,str(root/'simulation/trace.cjs'),'--strategy',strategy,'--seed',str(seed),'--candidate','cavalry','--output',str(tmp)],check=True,capture_output=True,text=True)
 item=json.loads(tmp.read_text());examples.append({'experiment':'candidate-cavalry3',**item['run']});tmp.unlink()
payload={'config':config,'configSHA256':hashlib.sha256((a.results/'config.json').read_bytes()).hexdigest(),'seedsPerStrategy':meta['count'],'totalCampaigns':sum(s['runs'] for e in experiments for s in e['summary']),'experiments':experiments,'examples':examples}
(out/'simulation-results.json').write_text(json.dumps(payload,indent=2)+'\n')
with (out/'simulation-comparison.csv').open('w',newline='') as f:
 w=csv.writer(f);cols=['experiment','strategy','runs','completed','completionRate','meanFights','meanReplays','meanDefeats','meanDraws','meanRounds','meanGold','meanSpent'];w.writerow(cols)
 for e in experiments:
  for row in e['summary']:w.writerow([e['id']]+[row[k] for k in cols[1:]])
with zipfile.ZipFile(out/'simulation-scripts.zip','w',zipfile.ZIP_DEFLATED) as z:
 for name in ['editor-balance.js','greenhaven-unit-balance.json','simulation/campaign-sim.js','simulation/editor-simulation.js','simulation/run.cjs','simulation/trace.cjs','simulation/check-formations.cjs','simulation/report.py','simulation/README.txt']:z.write(root/name,name)
with zipfile.ZipFile(out/'simulation-raw-runs.zip','w',zipfile.ZIP_DEFLATED) as z:
 for e in full:z.writestr(e['id']+'.json',json.dumps(e,indent=2)+'\n')
shutil.copy2(root/'simulation/README.txt',out/'simulation-model-notes.txt')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Greenhaven — gameplay simulation results</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#10191e;color:#e8efed;font:15px/1.6 system-ui,sans-serif}main{max-width:1250px;margin:auto;padding:35px 24px}h1{font:600 34px Georgia,serif;color:#edcc8d}h2{font-size:23px;margin-top:35px}p{color:#b6c8c4}a{color:#b9dfc6}section,details{background:#18272d;border:1px solid #34484e;border-radius:9px;padding:18px;margin:14px 0}.metrics{display:flex;gap:18px;flex-wrap:wrap}.metrics b{display:block;font-size:24px;color:#edcc8d}.metrics div{flex:1;min-width:150px;background:#18272d;padding:16px;border-radius:9px}select{font:inherit;padding:9px;background:#21373e;color:#e8efed;border:1px solid #58706e;max-width:100%}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;border-bottom:1px solid #34484e;padding:10px}th{color:#a7c8bc}.wrap{overflow:auto;max-height:660px}.rate{color:#a8e1bb;font-weight:650}.bad{color:#f2aaa0}summary{cursor:pointer;font-weight:650}.purchase{border-left:3px solid #bda566;padding-left:14px;margin:8px 0}.warning{color:#edcc8d}.links{display:flex;gap:16px;flex-wrap:wrap}.bar{height:5px;background:#8dc9a5;border-radius:4px}.fine{font-size:13px}
</style></head><body><main><div>GREENHAVEN · STATS-ONLY TESTING</div><h1>What happens when a player buys, upgrades and fights?</h1><p>The simulator runs the campaign without rendering the game. It records legal purchases, hex moves, attacks, summons, random encounters, rewards and unlocks. Five fixed shopping strategies use the same tactical bot.</p>
<div class="metrics" id="metrics"></div>
<h2>Current balance versus the tested candidate</h2><div class="wrap" id="headline"></div>
<p class="warning">These are completion frequencies for fixed bots and encounter seeds, not human win probabilities. Combat is deterministic. Native-style enemy movement is modeled independently; the native executable is not run. The stronger-AI column tests sensitivity to enemy pathfinding.</p>
<section><h2>What improved in testing</h2><ol>
<li><strong>Keep a safe earning route available.</strong> Allow replaying the already-won first Dark Forest stage for 20 gold, with no additional victory credit. This alone raised the mixed strategy from 51% to 100% completion in this model. Replaying the previous region's hardest group was not always safe.</li>
<li><strong>Reduce Demon HP from 4 to 3.</strong> This changes an important damage breakpoint: a 3-damage attack now defeats a Demon in one hit. With safe practice, mounted completion rose from 0% to 90% against native-style AI. The same smaller candidate still failed with stronger enemy pathfinding.</li>
<li><strong>Raise Cavalry damage from 2 to 3.</strong> Added to the candidate above, this raised mounted completion to 100% with native-style AI and 89.5% with pathfinding enemies. The remaining failures mean this is a promising candidate, not a final balance.</li>
</ol><p>The active editor and native-game balance values were kept. The candidate is downloadable separately and selectable in the editor's simulation controls.</p></section>
<section><h2>What did not work, and what still needs work</h2><ul>
<li>A Scout HP or damage increase alone did not rescue the mounted strategy across these seeds.</li>
<li>Reducing the fourth-slot cost from 40 to 15 made the mixed shopping plan worse (51% to 0%). The bot recruited a Scout before the Forest guard fight, changing its deployment and moves. It lost despite having an extra fighter. This exposes tactical-policy sensitivity; it is not proof that cheaper slots harm human players.</li>
<li>Infantry, archer and caster bots already completed every native-style baseline run. Test pressure and tactical challenge with humans before making the whole campaign easier.</li>
<li>Mounted failures with stronger enemy AI need another pass on positioning and cave encounters. Fixed army-slot activation and a bot that never sells or changes strategy can understate what a human can achieve. A separate check of all ten slot arrangements of two Swordsmen and three Cavalry still lost the baseline boss fight with this bot under both enemy policies.</li>
<li>The late economy accumulates spare gold after all planned upgrades. Chapel's recruit discount is not bought by these plans. Tier unlock timing, upgrade choices and that support effect need separate design tests; these recommendations have not been applied.</li>
</ul></section>
<h2>Inspect all experiments</h2><select id="experiment" aria-label="Experiment"></select><div class="wrap" id="comparison"></div><p class="fine">Mean fights and rounds include stopped campaigns. A short failed run is not a fast completion. Each strategy uses the same 200 starting seeds. Those seeds draw from a small authored pool; they are not independent playtest participants.</p>
<h2>Follow an example player</h2><p>Choose a strategy and configuration, then expand a fight for every movement step and attack. The same starting seed is used for that strategy's examples. Gold is conserved: starting gold + rewards − purchases = remaining gold.</p><select id="example" aria-label="Example campaign"></select><div id="timeline"></div>
<section><h2>Rules and evidence</h2><p>7×6 hex board, fixed trees, fixed damage, one attack per activation, movement AP, player phase then enemy phase, full army recovery, five player slots, twelve total allocated battle slots, Warlock summoning and immediate boss victory. The player bot uses pathfinding and focus fire. Shopping plans never inspect the next enemy group. No selling, replacement planning or human tactical decisions are modeled.</p><p>Tests check every one of the 1,764 distance/shot pairs against compiled native tables, purchase legality, money conservation, movement occupancy, AP limits, summoning, deterministic replay, progression and browser exports. These establish targeted rule checks, not complete native-engine equivalence.</p><div class="links"><a href="simulation-scripts.zip">Simulation scripts</a><a href="simulation-comparison.csv">Comparison CSV</a><a href="simulation-results.json">Summary and full example logs</a><a href="simulation-raw-runs.zip">Every campaign result</a><a href="simulation-candidate.json">Candidate configuration</a><a href="simulation-model-notes.txt">Model notes</a><a href="simulation-formation-check.json">Formation check</a></div></section>
<script id="data" type="application/json">PAYLOAD</script><script>
const data=JSON.parse(document.getElementById('data').textContent);
const node=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
function table(head,rows){const t=node('table'),h=node('thead'),r=node('tr'),b=node('tbody');for(const x of head)r.append(node('th',x));h.append(r);for(const values of rows){const tr=b.insertRow();for(const value of values)tr.insertCell().textContent=value;}t.append(h,b);return t;}
const byId=id=>data.experiments.find(e=>e.id===id),rate=(id,strategy)=>{const r=byId(id)?.summary.find(r=>r.strategy===strategy);return r?`${(r.completionRate*100).toFixed(1)}% (${r.completed}/${r.runs})`:'Not run';};
const cards=document.getElementById('metrics');for(const [n,label] of [[data.totalCampaigns.toLocaleString(),'campaigns'],[data.experiments.length,'balance / AI scenarios'],[5,'shopping strategies'],[data.seedsPerStrategy,'starting seeds per strategy']]){const c=node('div');c.append(node('b',n),node('span',label));cards.append(c);}
document.getElementById('headline').append(table(['Strategy','Current / native-style AI','Candidate / native-style AI','Candidate / pathfinding AI'],byId('baseline').summary.map(r=>[r.name,rate('baseline',r.strategy),rate('candidate-cavalry3',r.strategy),rate('candidate-cavalry3-pathfinding',r.strategy)])));
const select=document.getElementById('experiment');for(const e of data.experiments){const o=node('option',e.name);o.value=e.id;select.append(o);}select.value='baseline';
function comparison(){const e=byId(select.value),host=document.getElementById('comparison');host.replaceChildren(table(['Strategy','Completed','Mean fights','Mean replays','Mean defeats','Mean draws','Mean rounds','Mean gold left'],e.summary.map(r=>[r.name,`${r.completed}/${r.runs} (${(r.completionRate*100).toFixed(1)}%)`,r.meanFights.toFixed(2),r.meanReplays.toFixed(2),r.meanDefeats.toFixed(2),r.meanDraws.toFixed(2),r.meanRounds.toFixed(2),r.meanGold.toFixed(0)])));}select.addEventListener('change',comparison);comparison();
const names={baseline:'Current', 'practice-demon3':'Practice + Demon HP3','candidate-cavalry3':'Candidate incl. Cavalry damage3'},examples=document.getElementById('example');data.examples.forEach((r,i)=>{const o=node('option',`${names[r.experiment]||r.experiment} · ${r.strategy} · seed ${r.seed} · ${r.completed?'completed':'stopped'}`);o.value=i;examples.append(o);});examples.value=data.examples.findIndex(e=>e.experiment==='candidate-cavalry3'&&e.strategy==='mixed');
function timeline(){const r=data.examples[Number(examples.value)],host=document.getElementById('timeline');host.replaceChildren(node('h3',`${r.completed?'Completed':'Stopped'} · ${r.fights} fights · ${r.gold} gold left`));host.append(node('p',`${data.config.startingGold} start + ${r.earned} earned − ${r.spent} spent = ${r.gold}. Wins: ${r.wins.join(' / ')}.${r.blockedReason?' '+r.blockedReason:''}`));for(const e of r.events){if(e.type==='purchase'){const p=node('p',`Before fight ${e.beforeFight}: ${e.label} · ${e.cost} gold (${e.goldBefore} → ${e.goldAfter})`);p.className='purchase';host.append(p);continue;}const detail=node('details');detail.append(node('summary',`Fight ${e.fight} · ${e.regionName}, stage ${e.stage}${e.replay?' / practice':''} · ${e.outcome} · ${e.rounds} rounds · +${e.reward} gold`),node('p',`Seed ${e.seed}. Enemies: ${e.enemies.join(', ')}. Army: ${e.army.join(', ')}. Balance: ${e.goldAfter}.`));const wrap=node('div');wrap.className='wrap';wrap.append(table(['Round','Fighter','Action','What happened'],e.trace.map(t=>[t.round,t.unit||'Warlock',t.action,t.action==='move'?`hex ${t.from} → ${t.to}`:t.action==='attack'?`${t.targetName}: ${t.hpBefore} → ${t.hpAfter} HP`:t.action==='summon'?`Demon at hex ${t.to}`:t.reason||''])));detail.append(wrap);host.append(detail);}}
examples.addEventListener('change',timeline);timeline();
</script></main></body></html>'''
html=html.replace('PAYLOAD',json.dumps(payload,separators=(',',':')).replace('</','<\\/'))
(out/'simulation-report.html').write_text(html)
print('Report:',out/'simulation-report.html');print('Campaigns:',payload['totalCampaigns'])
